unsigned long icache_evict_oldest(struct inode_cache *ic) {
    if (ic->used == 0) return 0;

    struct inode_entry *victim = ic->slots[0];
    for (int i = 0; i < ic->used - 1; i++)
        ic->slots[i] = ic->slots[i + 1];
    ic->slots[ic->used - 1] = NULL;
    ic->used--;

    /* Fix: save data before freeing */
    unsigned long evicted_ino = victim->ino;
    char evicted_name[NAME_MAX_LEN];
    strncpy(evicted_name, victim->name, NAME_MAX_LEN - 1);
    evicted_name[NAME_MAX_LEN - 1] = '\0';

    free(victim);

    printf("evicted inode %lu: %s\n", evicted_ino, evicted_name);
    return evicted_ino;
}
